var result = result["split"]("")
["reverse"]()
["join"]("");

var Arr = new Array();

var len = Math["ceil"](result["length"] / 128);

for (var i = 0; i<len; i++) {
		var sub = result["substr"](128 * i, 128);
		if (i%2==0) {
				Arr["push"](
						sub["split"]("")["reverse"]()["join"]("")
					);
			}
		else {
				Arr["push"](sub);
			}
	}
result = Arr["join"]("")
["split"]("")
["reverse"]()
["join"]("");

decodeURIComponent(java.base64Decode(result));

