🔥 热度：{{$.hot}}{{$.hotLabel}}
🎗 标签：{{$..name##\s##，}}
🕰 更新时间：{{$.updateStatus}}
📂 简介：{{$..description}}##(^|[。！？]+[”」）】]?)##$1<br>

source.searchUrl:
@js:
var option = {   
        "method": "POST",
        "body": "app=midu&keyword={{key}}&page={{page-1}}"
    };
try{
	run;

"https://api.midureader.com/fiction/search/search,"+ JSON.stringify(option)
}
catch(e){
	"https://api.midureader.com/fiction/search/searchV2,"+ JSON.stringify(option)
	}

source.bookSourceComment:
//仅供学习研究使用，请在24h内删除
//同网址https://api.midukanshu.com/
/**
//目录url规则，获取目录url	https://api.midureader.com/fiction/book/getChaptersCdn,{"method": "POST","body": "app=midu&lastUpdatedTime=&bookId={{$.book_id}}"}
//目录列表规则，获取目录列表
$..url
<js>
url=String(result).match(/"(.*)"/) [1].replace(/\\/g,'').trim();
java.ajax(url)
//java.log(url)
</js>
$.[*]
*/

source.exploreUrl:
@js:
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});
$$ = (second_channel, status) => `/fiction/search/channel,{"method": "POST","body": "app=midu&second_channel=${second_channel}&status=${status}&page={{page-1}\}&rank="}`;
[
    [
        ["玄幻", 3],
        ["都市", 5],
        ["推理", 7],
        ["仙侠", 15],
        ["科幻", 27],
        ["游戏", 30],
        ["武侠", 32],
        ["历史", 35],
        ["奇幻", 39],
        ["军事", 93],
        ["体育", 47],
        ["现实", 79],
        ["同人", 61]
    ],
    [
        ["现代言情", 13],
        ["古代言情", 17],
        ["悬疑刑侦", 24],
        ["玄幻仙侠", 41],
        ["青春校园", 51],
        ["同人小说", 68],
        ["科幻空间", 78],
        ["游戏竞技", 95]
    ]
].map((Arr, isN) => {
    push("༺ˇ»`ʚ " + (isN ? "女" : "男") + "频 ɞ´«ˇ༻", null, 1);
    Arr.map([title, second_channel] => {
        ["[" + title + "]", "完结", "连载"].map((title, status) => {
            push(title, $$(second_channel, status), 0.25);
        });
    });
});
JSON.stringify(sort);

