source.ruleBookContent:
id.htmlContent@html@js:
if(baseUrl.match(/biquge1000.com/)){
result=result
}else{result=baseUrl.match(/text=(.*)/)[1]}
result = String(result).replace(/<img\s+[^>]+>/ig, '<p>〖插图，2.0暂不支持〗</p>');

source.ruleChapterList:
//div[@id="list-chapterAll"]/dl[@class="panel-body panel-chapterlist"]/*<js>
//按卷分隔
sub=String(result).slice(1,-1).split(/, (?=<dt class="col-md-12")/);
sm=java.getString("class.bookTitle@text");

if(sub.length>=1)for(var i=0;i<sub.length;i++){
//捕获卷名
jm=sub[i].match(/\s*([^<>\n]+)\s*<\/dt/);

sub[i]=sub[i].replace(/">(.*)<\/a/g,'">🍥'+jm[1]+'🍥$1<\/a');

//按卷分块
sub[i]='<dd class="col-md-3"><a href="https://translate.google.cn/#view=home&op=translate&sl=zh-CN&tl=en&text='+sm+'/'+jm[1]+'">♦'+jm[1]+'♦</a></dd>'+sub[i];
}
//合并结果
sub.join("")
</js>a

