function getImgList() {
var infoNum = html.match(/\/comic\/(\d{15})\.html/)[1];
var totalPages = infoNum.slice(-6,-3);
var chapter = infoNum.slice(5,8);
var comicNum = infoNum.slice(0,4);
var piclist = new Array(Number(totalPages));
var pages = new Array(Number(totalPages));
for (var x = 0; x <totalPages; x++){
pages[x] = ("00" + (x + 1)).slice(-3);
piclist[x] = "http://www.cartoonmad.com/home75388/" + comicNum + "/" + chapter + "/" + pages[x] + ".jpg";
}
return piclist;
}@Header:{Referer:host}

